import json, hashlib
ROOT=Path(__file__).resolve().parents[1]
def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def read(p): return json.loads((ROOT/p).read_text())
def write(p,x):
    with (ROOT/p).open('x') as f: json.dump(x,f,ensure_ascii=False,indent=2,allow_nan=False);f.write('\n')
    print(json.dumps(dict(path=p,sha256=sha(ROOT/p))))
